declare(strict_types=1);
namespace OCA\Mcp\Tests\Integration\Mail;
use OCA\Mcp\Tests\Integration\IntegrationTestCase;
use PHPUnit\Framework\Attributes\Group;
#[Group('mail')]
final class McpMailSnoozeTest extends IntegrationTestCase {
    private function proof(string $scenario):array {if(getenv('MCP_IT_MAIL_GUARD')!=='1')self::markTestSkipped('Native fixture only.');$r=MailActor::run(MailActor::ALICE,'snooze-native',['scenario'=>$scenario]);self::assertArrayNotHasKey('fixture_error',$r,json_encode($r));self::assertTrue($r['implementation_available'],'Guarded native snooze is required.');return $r;}
    public function testActualFairSweepReachesPreparedReadyAndRevokedIntentBehindTwentyFiveWaitingRows():void {foreach(['prepared'=>['placing','snoozed'],'ready'=>['snoozed','woken'],'revoked'=>['placing','blocked']]as$mode=>[$before,$after]){$r=$this->proof('mcp_fair_'.$mode);self::assertSame($before,$r['first_state'],$mode);self::assertSame($after,$r['final_state'],$mode);self::assertSame(25,$r['waiting_first'],$mode);self::assertTrue($r['target_dispatched'],$mode);self::assertTrue($r['fake_holds_retained'],$mode);}}
    public function testKnownFutureSnoozeCoexistsWithUnrelatedNativeTimersThreadsFoldersAndSeen():void {$r=$this->proof('coexist');foreach($r as$key=>$value)self::assertTrue($value,$key.' '.json_encode($r));}
    public function testNativeErasureCapturesOrphanSnoozesAndHonorsPhysicalOwnerLease():void {$r=$this->proof('erasure');self::assertTrue($r['ordinary_refused']);self::assertTrue($r['deleted']);self::assertTrue($r['independent']);self::assertSame(2,$r['busy_snoozes']);self::assertTrue($r['quarantined']);self::assertSame(0,$r['after_snoozes']);self::assertSame(0,$r['after_accounts']);self::assertTrue($r['unrelated']);}
    public function testMissingOriginalFolderBlocksWakeWithoutInboxFallback():void {$r=$this->proof('missing');self::assertSame('blocked',$r['blocked']);self::assertFalse($r['held_after']);self::assertSame($r['before'],$r['after']);}
    public function testOriginalGenerationChangeBlocksWakeWithoutFallback():void {$r=$this->proof('generation');self::assertSame('blocked',$r['blocked']);self::assertFalse($r['held_after']);self::assertSame($r['before'],$r['after']);}
    public function testActualToolsBindOriginalConnectionAndBothFolders():void {$r=$this->proof('mcp_cancel');self::assertTrue($r['fpm_unqualified_refused']);self::assertTrue($r['basic_refused']);self::assertSame('succeeded',$r['admission']);self::assertSame('snoozed',$r['state']);self::assertTrue($r['replayed']);self::assertTrue($r['id_preserved']);self::assertSame('cancelled',$r['cancelled']);}
    public function testActualExplicitWakeUsesBoundedSignedChild():void {$r=$this->proof('mcp_wake');self::assertSame('woken',$r['woken']);}
    public function testActualLostAdmissionAcknowledgementRecoversBeforePlacementWire():void {$r=$this->proof('mcp_lost_ack');self::assertSame('uncertain',$r['admission']);self::assertSame('placing',$r['state']);self::assertTrue($r['replayed']);self::assertSame('snoozed',$r['recovered_state']);}
    public function testActualFutureScopeWithdrawalBlocksAndHidesHistory():void {$r=$this->proof('mcp_scope');self::assertTrue($r['scope_status_denied']);self::assertTrue($r['scope_replay_denied']);self::assertSame('blocked',$r['blocked']);self::assertTrue($r['audit_metadata_only']);}
    public function testActualCancellationReauthorizesImmediatelyBeforeCommit():void {$r=$this->proof('mcp_cancel_revoke');self::assertTrue($r['refused']);self::assertSame('snoozed',$r['native_state']);}
    public function testNativeUiAndLowerDestructivePathsRefuseBeforeAnyMove():void {$r=$this->proof('holds');foreach($r['holds']as$path=>$held)self::assertTrue($held,$path);self::assertCount(5,$r['remote']);}
    public function testEventFailureRetainsDurableMoveProofAndNeverRedispatches():void {$r=$this->proof('event_failure');self::assertSame('snoozed',$r['placed']['state']);self::assertSame('cache_pending',$r['placed']['placementPhase']);self::assertSame(1,$r['events']);self::assertSame('moved',$r['proof']['outcome']);}
    public function testNativeSnoozeProtocolFaultsNeverRetryUnknownMoves():void {foreach(['lost_ack','missing_map','wrong_source','multiple','destination_generation_after','wake_lost_ack']as$mode){$r=$this->proof('protocol_'.$mode);self::assertSame('uncertain',$r['native']['state'],$mode);self::assertSame(1,$r['moves'],$mode);self::assertSame(1,$r['clients'],$mode);self::assertSame(0,$r['forbidden'],$mode);self::assertTrue($r['held_after'],$mode);self::assertTrue($r['cancel_refused'],$mode);}}
    public function testUnsupportedProviderRefusesBeforeWireAndCannotAutoRetry():void {$r=$this->proof('protocol_no_move');self::assertSame('blocked',$r['native']['state']);self::assertSame('failed_before_effect',$r['native']['placementPhase']);self::assertSame(0,$r['moves']);self::assertSame(1,$r['clients']);self::assertFalse($r['held_after']);}
    public function testPlacementAndWakeUseNewExactUidsAndNeverTheStockTimer():void {$r=$this->proof('roundtrip');self::assertSame('snoozed',$r['placed']['state']);self::assertNull($r['placed']['currentMessageId']);self::assertSame('woken',$r['woken']['state']);self::assertNotSame($r['woken']['original']['uid'],$r['woken']['current']['uid']);self::assertNotSame($r['source_id'],$r['resolved_id']);self::assertSame(0,$r['legacy']);self::assertTrue($r['no_send']);}
    public function testCancellationLeavesTheMessageAndReleasesKnownHold():void {$r=$this->proof('cancel');self::assertSame('cancelled',$r['cancelled']['state']);self::assertTrue($r['held_before']);self::assertFalse($r['held_after']);self::assertSame($r['before'],$r['after']);}
    public function testFutureMetadataWithdrawalBlocksAndUnknownPolicyPreservesHold():void {$r=$this->proof('audit');self::assertSame('placing',$r['unknown']);self::assertSame('blocked',$r['blocked']);self::assertFalse($r['held_after']);self::assertTrue($r['no_send']);}
    public function testCancellationRevocationAtPrecommitRollsBack():void {$r=$this->proof('cancel_fence');self::assertTrue($r['refused']);self::assertSame('snoozed',$r['state']);self::assertTrue($r['held_after']);}
    public function testWakeWaitsForNativeCacheThenRefusesDuplicateUidRows():void {$r=$this->proof('cache');self::assertSame('waiting_cache',$r['waiting']);self::assertTrue($r['duplicate_refused']);self::assertSame('snoozed',$r['state']);}
    public function testPhysicalOwnerAndBothMailboxLeasesRefuseIndependentSession():void {$r=$this->proof('leases');self::assertSame([true,true,true],$r['contenders']);}
    public function testDurableWireClaimCannotBeCancelledOrRetried():void {$r=$this->proof('unknown');self::assertSame('uncertain',$r['state']);self::assertTrue($r['refused']);self::assertTrue($r['held_after']);self::assertSame($r['before'],$r['after']);}
}
